from moler.device import DeviceFactory


class CustomDeviceFactory:

    def __init__(self, device_name, cloned=True, new_device_name=None, **device_kwargs):
        device = DeviceFactory.get_device(name=device_name, establish_connection=False, **device_kwargs)
        if cloned is True:
            new_device_name = new_device_name or device_name + "_CUSTOM"
            self.device = DeviceFactory.get_cloned_device(source_device=device, new_name=new_device_name,
                                                          establish_connection=False, **device_kwargs)
        else:
            self.device = device
        self.old_get_packages = self.device._get_packages_for_state

    def modfy_get_packages_for_state(self, new_state, cmds=None, events=None, additional_packages=None):
        default_cmds = ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.shared.enblinux']
        if additional_packages:
            default_cmds += additional_packages
        cmds = cmds or default_cmds
        events = events or ['moler.events.shared', 'moler.events.unix']
        old_func = self.device._get_packages_for_state

        def modified_get_packages_for_state(state, observer, *args, **kwargs):
            packages = old_func(*args, state=state, observer=observer, **kwargs)
            if new_state == state and observer == "event":
                return events
            elif new_state == state and observer == "cmd":
                return cmds
            return packages

        self.device._get_packages_for_state = modified_get_packages_for_state

    def remove_transitions_for_states(self, source_state, dest_state):
        transitions = self.device.SM.events
        for trigger, events in dict(transitions).items():
            for transition in events.transitions.values():
                transition = transition[0]
                if transition.source == source_state and transition.dest == dest_state:
                    self.device.SM.remove_transition(trigger, transition.source, transition.dest)
                elif transition.source == dest_state and transition.dest == source_state:
                    self.device.SM.remove_transition(trigger, transition.source, transition.dest)

    def add_transitions(self, transitions):
        self.device._add_transitions(transitions)

    def add_state_for_hops(self, source_state, dest_state, new_state):
        for state, hops in self.device._state_hops.items():
            if state == source_state:
                new_state_hops = dict(hops)
                if dest_state is not None:
                    for hop_source, hop_dest in hops.items():
                        if hop_dest == dest_state:
                            hops[hop_source] = new_state
                    hops[dest_state] = new_state
            elif dest_state is not None and state == dest_state:
                for hop_source, hop_dest in hops.items():
                    if hop_dest == source_state:
                        hops[hop_source] = new_state
                hops[source_state] = new_state
            else:
                if dest_state is not None and dest_state in hops.keys():
                    hops[new_state] = hops[dest_state]
                elif source_state in hops.keys():
                    hops[new_state] = hops[source_state]
                else:
                    hops[new_state] = source_state
        source_state_transitions = {transi.source: transi.dest for transi in self.device.SM.get_transitions()
                                    if transi.dest == source_state}
        for state in new_state_hops.keys():
            new_state_hops[state] = source_state
        for state in source_state_transitions.keys():
            if state != new_state and state != dest_state:
                new_state_hops[state] = source_state
        self.device._state_hops[new_state] = new_state_hops

    def change_configuration_for_state(self, source_state, new_state, dest_state=None, new_state_configuration=None,
                                       from_dest_state_to_new_state=None, from_source_state_to_new_state=None,
                                       from_new_state_to_source_state=None, form_new_state_to_dest_state=None):
        new_state_configuration = new_state_configuration or {}
        for state, hops in self.device._configurations["CONNECTION_HOPS"].items():
            if state == source_state:
                if dest_state is not None:
                    form_new_state_to_dest_state = form_new_state_to_dest_state or hops[dest_state]
                    del hops[dest_state]
                hops[new_state] = from_source_state_to_new_state
            elif dest_state is not None and state == dest_state:
                from_new_state_to_source_state = from_new_state_to_source_state or hops[source_state]
                del hops[source_state]
                hops[new_state] = from_dest_state_to_new_state
        if dest_state is not None:
            new_state_configuration[dest_state] = form_new_state_to_dest_state
        new_state_configuration[source_state] = from_new_state_to_source_state
        self.device._configurations["CONNECTION_HOPS"][new_state] = new_state_configuration

    def set_prompt_for_new_state(self, new_state, prompt):
        self.device._state_prompts[new_state] = prompt


def add_namespace_state_for_device(device_name, dest_state, namespace_name, new_device_name=None, cloned=True):
    device = CustomDeviceFactory(device_name, cloned=cloned, new_device_name=new_device_name)
    from_source_state_to_new_state = {
        "execute_command": "sudo",
        "command_params": {
            "sudo_params": 'ip netns exec {} bash -c "su - ute"'.format(namespace_name),
            "expected_prompt": "^uteNamespace.*",
            "prompt_after_login": "ute@.*(\\$|#|>)\\s+",
            "target_newline": "",
            "set_prompt": r'export PS1="uteNamespace:\W\$"'}
    }
    from_dest_state_to_new_state = {
        "execute_command": "exit",
        "command_params": {
            "expected_prompt": "uteNamespace.*"
        },
        "required_command_params": [
            "expected_prompt"
        ]
    }
    from_new_state_to_source_state = {
        "execute_command": "exit",
        "command_params": {
            "expected_prompt": "ute@.*(\\$|#|>)\\s+"
        },
        "required_command_params": [
            "expected_prompt"
        ]
    }
    transitions = {
        "PROXY_PC": {
            "NAMESPACE": {
                "action": [
                    "_execute_command_to_change_state"
                ],
            }
        },
        "NAMESPACE": {
            "PROXY_PC": {
                "action": [
                    "_execute_command_to_change_state"
                ],
            },
            dest_state: {
                "action": [
                    "_execute_command_to_change_state"
                ],
            },
        },
        dest_state: {
            "NAMESPACE": {
                "action": [
                    "_execute_command_to_change_state"
                ],
            }
        },
    }
    device.remove_transitions_for_states(source_state="PROXY_PC", dest_state=dest_state)
    device.change_configuration_for_state(source_state="PROXY_PC", dest_state=dest_state, new_state="NAMESPACE",
                                          from_dest_state_to_new_state=from_dest_state_to_new_state,
                                          from_source_state_to_new_state=from_source_state_to_new_state,
                                          from_new_state_to_source_state=from_new_state_to_source_state)
    device.add_transitions(transitions=transitions)
    device.add_state_for_hops(source_state="PROXY_PC", dest_state=dest_state, new_state="NAMESPACE")
    device.modfy_get_packages_for_state(new_state="NAMESPACE")
    device.set_prompt_for_new_state("NAMESPACE", r'^uteNamespace.*')
    return device


def add_telnet_state_for_device(device_name, source_state, new_device_name=None, cloned=True):
    device = CustomDeviceFactory(device_name, new_device_name=new_device_name, cloned=cloned)
    from_source_state_to_new_state = {
        "execute_command": "telnet",
        "command_params": {
            "host": 0,
            "port": 15007,
            "expected_prompt": "AaShell>"}
    }
    from_new_state_to_source_state = {
        "execute_command": "run_script",
        "command_params": {
            "script_command": "quit",
        }
    }
    transitions = {
        "TELNET": {
            source_state: {
                "action": [
                    "_execute_command_to_change_state"
                ],
            },
        },
        source_state: {
            "TELNET": {
                "action": [
                    "_execute_command_to_change_state"
                ],
            }
        },
    }
    device.change_configuration_for_state(source_state="RU", new_state="TELNET",
                                          from_source_state_to_new_state=from_source_state_to_new_state,
                                          from_new_state_to_source_state=from_new_state_to_source_state)
    device.add_transitions(transitions)
    device.add_state_for_hops(source_state=source_state, dest_state=None, new_state="TELNET")
    device.modfy_get_packages_for_state("TELNET")
    return device


def add_rfsw_state_for_device(device_name, source_state, new_device_name=None, cloned=True):
    device = CustomDeviceFactory(device_name, new_device_name=new_device_name, cloned=cloned)
    from_source_state_to_new_state = {
        "execute_command": "rfsw_cli",
        "command_params": {
        }
    }
    from_new_state_to_source_state = {
        "execute_command": "exit",
        "command_params": {
            "expected_prompt": device.device._state_prompts[source_state]
        }
    }

    transitions = {
        "RFSW": {
            source_state: {
                "action": [
                    "_execute_command_to_change_state"
                ],
            },
        },
        source_state: {
            "RFSW": {
                "action": [
                    "_execute_command_to_change_state"
                ],
            }
        },
    }
    device.change_configuration_for_state(source_state="RU", new_state="RFSW",
                                          from_source_state_to_new_state=from_source_state_to_new_state,
                                          from_new_state_to_source_state=from_new_state_to_source_state)
    device.add_transitions(transitions)
    device.add_state_for_hops(source_state="RU", dest_state=None, new_state="RFSW")
    device.modfy_get_packages_for_state("RFSW", additional_packages=["ta_moler.cmd.hub.linux"])
    return device
